CREATE OR REPLACE FUNCTION cv.accept_intake(proof text, displayed_publication uuid, displayed_snapshot uuid, displayed_consent uuid, applicant_name text, email text, phone text, explicit_consent boolean, operation_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE g cv.public_upload_grant; p cv.publication; resource jsonb; s uuid; intent uuid; doc uuid; result uuid;
 h cv.digest; existing cv.intake; cap integer; retention_seconds integer; expiry timestamptz; BEGIN
 SELECT * INTO g FROM cv.public_upload_grant WHERE proof_digest=encode(sha256(convert_to(proof,'UTF8')),'hex');
 IF NOT FOUND THEN RAISE EXCEPTION 'INTAKE_UNAVAILABLE' USING ERRCODE='42501'; END IF;
 SELECT * INTO p FROM cv.publication WHERE (tenant_id,id)=(g.tenant_id,g.publication_id) FOR UPDATE;
 IF NOT FOUND OR NOT cv.publication_open(p.tenant_id,p.id) OR p.id IS DISTINCT FROM displayed_publication
 OR p.snapshot_id IS DISTINCT FROM displayed_snapshot OR g.snapshot_id IS DISTINCT FROM displayed_snapshot OR p.consent_policy_id IS DISTINCT FROM displayed_consent
 OR NOT explicit_consent OR explicit_consent IS NULL OR g.expires_at<=clock_timestamp()
 THEN RAISE EXCEPTION 'INTAKE_UNAVAILABLE' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM cv.policy_version WHERE tenant_id=p.tenant_id AND id IN
 (p.purpose_id,p.source_policy_id,p.consent_policy_id,p.retention_policy_id,p.erasure_policy_id,p.resource_policy_id)
 ORDER BY id FOR SHARE;
 SELECT definition INTO resource FROM cv.policy_version WHERE (tenant_id,id)=(p.tenant_id,p.resource_policy_id);
 cap:=(resource->>'public_submission_quota')::integer;
 SELECT (definition->>'retention_seconds')::integer INTO retention_seconds FROM cv.policy_version
 WHERE (tenant_id,id)=(p.tenant_id,p.retention_policy_id);
 IF cap IS NULL OR cap<=0 OR retention_seconds IS NULL OR retention_seconds<=0 OR
 (resource->>'max_pdf_bytes') IS NULL OR g.byte_count>(resource->>'max_pdf_bytes')::bigint OR
 coalesce(btrim(applicant_name),'')='' OR coalesce(btrim(email),'')='' AND coalesce(btrim(phone),'')='' OR
 length(applicant_name)>coalesce((resource->>'contact_max_characters')::integer,0) OR
 length(coalesce(email,''))>coalesce((resource->>'contact_max_characters')::integer,0) OR
 length(coalesce(phone,''))>coalesce((resource->>'contact_max_characters')::integer,0)
 THEN RAISE EXCEPTION 'INTAKE_INVALID' USING ERRCODE='23514'; END IF;
 h:=encode(sha256(convert_to(jsonb_build_array(displayed_publication,displayed_snapshot,displayed_consent,
 applicant_name,email,phone,g.content_digest,explicit_consent)::text,'UTF8')),'hex');
 SELECT * INTO existing FROM cv.intake WHERE tenant_id=p.tenant_id AND publication_id=p.id AND intake.operation_key=accept_intake.operation_key;
 IF FOUND THEN
  IF existing.payload_digest<>h OR existing.upload_grant_id<>g.id OR NOT EXISTS(SELECT 1 FROM cv.privacy_scope
  WHERE (tenant_id,id)=(existing.tenant_id,existing.scope_id) AND revoked_at IS NULL AND consent_expires_at>clock_timestamp())
  THEN RAISE EXCEPTION 'INTAKE_CONFLICT' USING ERRCODE='23514'; END IF;
  PERFORM cv.register_obligation('public',p.tenant_id,NULL,existing.receipt);
  RETURN existing.receipt;
 END IF;
 IF g.scope_id IS NOT NULL OR (SELECT count(*) FROM cv.intake WHERE tenant_id=p.tenant_id AND publication_id=p.id)>=cap
 THEN RAISE EXCEPTION 'INTAKE_LIMIT' USING ERRCODE='23514'; END IF;
 SELECT least(clock_timestamp()+make_interval(secs=>retention_seconds),min(expires_at)) INTO expiry
 FROM cv.policy_version WHERE tenant_id=p.tenant_id AND id IN
 (p.purpose_id,p.source_policy_id,p.consent_policy_id,p.retention_policy_id,p.erasure_policy_id,p.resource_policy_id);
 s:=gen_random_uuid();intent:=gen_random_uuid();doc:=gen_random_uuid();result:=gen_random_uuid();
 INSERT INTO cv.privacy_scope VALUES(p.tenant_id,s,NULL,p.purpose_id,gen_random_uuid(),p.source_policy_id,
 p.consent_policy_id,p.retention_policy_id,p.erasure_policy_id,p.resource_policy_id,
 clock_timestamp(),expiry,NULL,g.synthetic,clock_timestamp());
 UPDATE cv.public_upload_grant SET scope_id=s WHERE (tenant_id,id)=(g.tenant_id,g.id);
 INSERT INTO cv.contact_revision VALUES(p.tenant_id,s,gen_random_uuid(),1,applicant_name,email,phone,NULL);
 -- A validated grant supplies a durable database intent, not a physical-file success claim.
 INSERT INTO cv.file_intent VALUES(p.tenant_id,s,intent,g.object_key,'intake','committed',g.byte_count,g.content_digest,expiry,1);
 INSERT INTO cv.document_version VALUES(p.tenant_id,s,doc,intent,1,g.content_digest,'application/pdf',g.byte_count,g.validated_at,clock_timestamp());
 INSERT INTO cv.intake VALUES(p.tenant_id,s,gen_random_uuid(),p.id,p.snapshot_id,g.id,doc,result,operation_key,h,
 clock_timestamp(),g.validated_at,1,'pending');
 IF NOT cv.publication_open(p.tenant_id,p.id) THEN RAISE EXCEPTION 'INTAKE_UNAVAILABLE' USING ERRCODE='42501'; END IF;
 PERFORM cv.register_obligation('public',p.tenant_id,NULL,result);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION cv.advisory_child_check()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE construction xid8;
BEGIN
 IF TG_TABLE_NAME='advisory_manifest_evidence' THEN
  SELECT construction_xid INTO construction FROM cv.advisory_manifest
  WHERE (tenant_id,scope_id,id)=(NEW.tenant_id,NEW.scope_id,NEW.manifest_id);
 ELSE
  SELECT construction_xid INTO construction FROM cv.advisory_run
  WHERE (tenant_id,scope_id,id)=(NEW.tenant_id,NEW.scope_id,NEW.run_id);
 END IF;
 IF construction IS DISTINCT FROM pg_current_xact_id() THEN
  RAISE EXCEPTION 'ADVISORY_CHILD_SET_SEALED' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION cv.auth_bootstrap(i uuid, proof text, agency_name text, login text, credential text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE deadline timestamptz; result uuid; BEGIN
 SELECT startup_expires_at INTO deadline FROM cv.auth_installation WHERE singleton FOR UPDATE;
 result:=cv.auth_bootstrap_0018(i,proof,agency_name,login,credential);
 IF deadline IS NULL OR deadline<=clock_timestamp() THEN
  RAISE EXCEPTION 'BOOTSTRAP_EXPIRED' USING ERRCODE='42501'; END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION cv.auth_bootstrap_0018(i uuid, proof text, agency_name text, login text, credential text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE w cv.auth_installation; t uuid; u uuid; BEGIN
 SELECT * INTO w FROM cv.auth_installation WHERE singleton FOR UPDATE;
 IF NOT FOUND OR w.instance_id IS DISTINCT FROM i OR w.state<>'new'
 OR w.startup_digest IS DISTINCT FROM encode(sha256(convert_to(proof,'UTF8')),'hex')
 OR w.startup_expires_at IS NULL OR w.startup_expires_at<=clock_timestamp()
 OR (w.realm='server' AND session_user<>'cv_migrator')
 OR (w.realm='local' AND session_user NOT IN ('cv_runtime','cv_migrator'))
 OR w.realm IS NULL OR EXISTS(SELECT 1 FROM cv.agency)
 THEN RAISE EXCEPTION 'BOOTSTRAP_DENIED' USING ERRCODE='42501'; END IF;
 IF credential NOT LIKE '$argon2id$v=19$%' OR credential IS NULL
 OR login !~ '^[a-z0-9][a-z0-9._-]{0,63}$' OR login IS NULL
 OR coalesce(length(btrim(agency_name)),0) NOT BETWEEN 1 AND 200 THEN
  RAISE EXCEPTION 'INPUT_INVALID' USING ERRCODE='23514'; END IF;
 t:=gen_random_uuid(); u:=gen_random_uuid();
 INSERT INTO cv.agency(id,realm_key,name) VALUES(t,w.realm_key,agency_name);
 INSERT INTO cv.staff_user(tenant_id,id,login_name,credential_hash,active) VALUES(t,u,login,credential,true);
 INSERT INTO cv.membership VALUES(t,u,'admin',true,1);
 UPDATE cv.auth_installation SET state='initialized',tenant_id=t,startup_digest=NULL,
 startup_expires_at=NULL WHERE singleton;
 INSERT INTO cv.auth_audit(instance_id,actor_id,action,record_id) VALUES(i,u,'bootstrap',t);
 RETURN t;
END $function$

CREATE OR REPLACE FUNCTION cv.auth_login_begin(i uuid, login text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE w cv.auth_installation; a cv.auth_attempt; h cv.digest; u cv.staff_user;
 instant timestamptz; window_seconds integer; BEGIN
 SELECT * INTO w FROM cv.auth_installation WHERE singleton FOR UPDATE;
 IF NOT FOUND OR w.instance_id IS DISTINCT FROM i OR w.state<>'initialized' THEN
  RETURN jsonb_build_object('admitted',false); END IF;
 instant:=clock_timestamp(); window_seconds:=(w.policy->>'attempt_window_seconds')::integer;
 IF w.window_started+make_interval(secs=>window_seconds)<=instant THEN
  UPDATE cv.auth_installation SET window_started=instant,attempts=0 WHERE singleton;
  w.attempts:=0;
  DELETE FROM cv.auth_attempt WHERE window_started+make_interval(secs=>window_seconds)<=instant;
 END IF;
 IF w.attempts>=(w.policy->>'global_attempt_limit')::integer THEN
  RETURN jsonb_build_object('admitted',false); END IF;
 UPDATE cv.auth_installation SET attempts=attempts+1 WHERE singleton;
 h:=encode(sha256(convert_to(login,'UTF8')),'hex');
 SELECT * INTO a FROM cv.auth_attempt WHERE login_digest=h;
 IF FOUND AND a.window_started+make_interval(secs=>window_seconds)>instant THEN
  IF a.attempts>=(w.policy->>'account_attempt_limit')::integer THEN
   RETURN jsonb_build_object('admitted',false); END IF;
  UPDATE cv.auth_attempt SET attempts=attempts+1 WHERE login_digest=h;
 ELSE
  INSERT INTO cv.auth_attempt VALUES(h,instant,1) ON CONFLICT(login_digest)
  DO UPDATE SET window_started=excluded.window_started,attempts=1;
 END IF;
 SELECT s.* INTO u FROM cv.staff_user s JOIN cv.membership m ON (m.tenant_id,m.user_id)=(s.tenant_id,s.id)
 WHERE s.tenant_id=w.tenant_id AND s.login_name=login AND s.active AND m.active FOR SHARE OF s,m;
 IF NOT FOUND THEN RETURN jsonb_build_object('admitted',true,'credential',NULL); END IF;
 RETURN jsonb_build_object('admitted',true,'credential',
  jsonb_build_object('user_id',u.id,'credential_hash',u.credential_hash));
END $function$

CREATE OR REPLACE FUNCTION cv.auth_login_begin_0018(i uuid, login text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE w cv.auth_installation; a cv.auth_attempt; h cv.digest; u cv.staff_user;
 instant timestamptz; window_seconds integer; BEGIN
 SELECT * INTO w FROM cv.auth_installation WHERE singleton FOR UPDATE;
 IF NOT FOUND OR w.instance_id IS DISTINCT FROM i OR w.state<>'initialized' THEN RETURN NULL; END IF;
 instant:=clock_timestamp(); window_seconds:=(w.policy->>'attempt_window_seconds')::integer;
 IF w.window_started+make_interval(secs=>window_seconds)<=instant THEN
  UPDATE cv.auth_installation SET window_started=instant,attempts=0 WHERE singleton;
  w.attempts:=0;
  DELETE FROM cv.auth_attempt WHERE window_started+make_interval(secs=>window_seconds)<=instant;
 END IF;
 IF w.attempts>=(w.policy->>'global_attempt_limit')::integer THEN RETURN NULL; END IF;
 UPDATE cv.auth_installation SET attempts=attempts+1 WHERE singleton;
 h:=encode(sha256(convert_to(login,'UTF8')),'hex');
 SELECT * INTO a FROM cv.auth_attempt WHERE login_digest=h;
 IF FOUND AND a.window_started+make_interval(secs=>window_seconds)>instant THEN
  IF a.attempts>=(w.policy->>'account_attempt_limit')::integer THEN RETURN NULL; END IF;
  UPDATE cv.auth_attempt SET attempts=attempts+1 WHERE login_digest=h;
 ELSE
  INSERT INTO cv.auth_attempt VALUES(h,instant,1) ON CONFLICT(login_digest)
  DO UPDATE SET window_started=excluded.window_started,attempts=1;
 END IF;
 SELECT s.* INTO u FROM cv.staff_user s JOIN cv.membership m ON (m.tenant_id,m.user_id)=(s.tenant_id,s.id)
 WHERE s.tenant_id=w.tenant_id AND s.login_name=login AND s.active AND m.active FOR SHARE OF s,m;
 IF NOT FOUND THEN RETURN NULL; END IF;
 RETURN jsonb_build_object('user_id',u.id,'credential_hash',u.credential_hash);
END $function$

CREATE OR REPLACE FUNCTION cv.auth_login_finish(i uuid, u uuid, observed_hash text, token_hash cv.digest)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE w cv.auth_installation; actor cv.staff_user; member cv.membership;
 sid uuid; expiry timestamptz; BEGIN
 SELECT * INTO w FROM cv.auth_installation WHERE singleton FOR UPDATE;
 IF w.instance_id IS DISTINCT FROM i OR w.state<>'initialized' OR token_hash IS NULL THEN
  RAISE EXCEPTION 'AUTH_DENIED' USING ERRCODE='42501'; END IF;
 SELECT * INTO actor FROM cv.staff_user WHERE (tenant_id,id)=(w.tenant_id,u) FOR SHARE;
 SELECT * INTO member FROM cv.membership WHERE (tenant_id,user_id)=(w.tenant_id,u) FOR SHARE;
 IF actor.id IS NULL OR member.user_id IS NULL OR NOT actor.active OR NOT member.active
 OR actor.credential_hash IS DISTINCT FROM observed_hash THEN
  RAISE EXCEPTION 'AUTH_DENIED' USING ERRCODE='42501'; END IF;
 -- Refuse rather than silently evicting another device's live session.
 IF (SELECT count(*) FROM cv.staff_session WHERE (tenant_id,user_id)=(w.tenant_id,u)
 AND revoked_at IS NULL AND expires_at>clock_timestamp())>=(w.policy->>'session_limit')::integer
 THEN RETURN NULL; END IF;
 sid:=gen_random_uuid(); expiry:=clock_timestamp()+make_interval(secs=>(w.policy->>'session_ttl_seconds')::integer);
 INSERT INTO cv.staff_session(tenant_id,id,user_id,token_digest,expires_at)
 VALUES(w.tenant_id,sid,u,token_hash,expiry);
 INSERT INTO cv.auth_session VALUES(w.tenant_id,sid,i);
 INSERT INTO cv.auth_audit(instance_id,actor_id,action,record_id) VALUES(i,u,'login',sid);
 RETURN jsonb_build_object('instance_id',i,'tenant_id',w.tenant_id,'user_id',u,'session_id',sid,
 'login_name',actor.login_name,'role',member.role,'expires_at',expiry);
END $function$

CREATE OR REPLACE FUNCTION cv.auth_logout()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE a jsonb; BEGIN
 a:=cv.auth_current();
 -- This is the final command: validate all outstanding authority before consuming this session.
 PERFORM cv.validate_transaction();
 INSERT INTO cv.auth_audit(instance_id,actor_id,action,record_id)
 VALUES((a->>'instance_id')::uuid,(a->>'user_id')::uuid,'logout',(a->>'session_id')::uuid);
 UPDATE cv.staff_session SET revoked_at=clock_timestamp()
 WHERE (tenant_id,id)=((a->>'tenant_id')::uuid,(a->>'session_id')::uuid);
 DELETE FROM cv.transaction_context WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id();
END $function$

CREATE OR REPLACE FUNCTION cv.auth_policy_obligations()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
BEGIN
 IF to_regclass('pg_temp.cv_auth_policy_obligations') IS NULL THEN
  CREATE TEMPORARY TABLE cv_auth_policy_obligations (
   tenant_id uuid NOT NULL, policy_id uuid NOT NULL,
   transaction_id xid8 NOT NULL DEFAULT pg_current_xact_id(),
   PRIMARY KEY(tenant_id,policy_id)
  ) ON COMMIT DROP;
  ALTER TABLE pg_temp.cv_auth_policy_obligations ENABLE ROW LEVEL SECURITY;
  ALTER TABLE pg_temp.cv_auth_policy_obligations FORCE ROW LEVEL SECURITY;
  CREATE POLICY guard ON pg_temp.cv_auth_policy_obligations TO cv_guard USING(true) WITH CHECK(true);
  REVOKE ALL ON pg_temp.cv_auth_policy_obligations FROM PUBLIC;
 ELSIF (SELECT pg_get_userbyid(relowner) FROM pg_class
 WHERE oid=to_regclass('pg_temp.cv_auth_policy_obligations'))<>'cv_guard' THEN
  RAISE EXCEPTION 'AUTH_CONTEXT_INVALID' USING ERRCODE='42501';
 END IF;
END $function$

CREATE OR REPLACE FUNCTION cv.auth_policy_write(op text, key uuid, payload cv.digest, body jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE result jsonb; a jsonb; p uuid; BEGIN
 result:=cv.auth_policy_write_0019(op,key,payload,body);
 IF op IN ('policy-activate','purpose-grant') THEN
  a:=cv.auth_current();
  p:=CASE WHEN op='policy-activate' THEN (result->>'policy_id')::uuid ELSE (result->>'purpose_id')::uuid END;
  PERFORM cv.auth_policy_obligations();
  INSERT INTO pg_temp.cv_auth_policy_obligations(tenant_id,policy_id)
  VALUES((a->>'tenant_id')::uuid,p) ON CONFLICT DO NOTHING;
 END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION cv.auth_policy_write_0019(op text, key uuid, payload cv.digest, body jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE a jsonb; w cv.auth_installation; prior cv.auth_command; result jsonb;
 p uuid; u uuid; v cv.policy_version; old_revision integer; active_value boolean; owner text;
BEGIN
 a:=cv.auth_current(); PERFORM cv.require_authority((a->>'tenant_id')::uuid,true);
 SELECT * INTO w FROM cv.auth_installation WHERE singleton FOR UPDATE;
 IF key IS NULL OR payload IS NULL OR op NOT IN ('policy-activate','policy-revoke','purpose-grant') THEN
  RAISE EXCEPTION 'INPUT_INVALID' USING ERRCODE='23514'; END IF;
 SELECT * INTO prior FROM cv.auth_command WHERE (instance_id,actor_id,operation,operation_key)=
 (w.instance_id,(a->>'user_id')::uuid,op,key);
 IF FOUND THEN
  IF prior.payload_digest<>payload THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT' USING ERRCODE='23514'; END IF;
  RETURN prior.result;
 END IF;
 IF op='policy-activate' THEN
  IF body->>'kind' NOT IN ('source','purpose','consent','retention','erasure','resource')
  OR body->>'kind' IS NULL OR coalesce(btrim(body->>'version'),'')=''
  OR (body->>'expires_at')::timestamptz<=clock_timestamp() OR body->>'expires_at' IS NULL
  OR (body->'definition'->>'synthetic_only') IS DISTINCT FROM 'true'
  OR (body->'definition'->>'production_approval') IS DISTINCT FROM 'false'
  OR (body->'definition'->>'clock') IS DISTINCT FROM 'database-utc' THEN
   RAISE EXCEPTION 'POLICY_INVALID' USING ERRCODE='23514'; END IF;
  p:=gen_random_uuid(); owner:=CASE WHEN w.realm='local' THEN 'workspace-admin' ELSE 'agency-admin' END;
  INSERT INTO cv.policy_version VALUES(w.tenant_id,p,body->>'kind',body->>'version',
   (a->>'user_id')::uuid,owner,true,clock_timestamp(),(body->>'expires_at')::timestamptz,body->'definition');
  result:=jsonb_build_object('policy_id',p,'kind',body->>'kind','version',body->>'version',
   'owner_user_id',a->>'user_id','owner_role',owner,'expires_at',body->>'expires_at',
   'revoked',false,'definition',body->'definition');
 ELSIF op='policy-revoke' THEN
  p:=(body->>'policy_id')::uuid;
  SELECT * INTO v FROM cv.policy_version WHERE (tenant_id,id)=(w.tenant_id,p) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ACCESS_DENIED' USING ERRCODE='42501'; END IF;
  IF coalesce(btrim(body->>'reason'),'')='' THEN RAISE EXCEPTION 'INPUT_INVALID' USING ERRCODE='23514'; END IF;
  INSERT INTO cv.policy_revocation VALUES(w.tenant_id,p,clock_timestamp(),(a->>'user_id')::uuid,body->>'reason')
  ON CONFLICT DO NOTHING;
  result:=jsonb_build_object('committed',true);
 ELSE
  p:=(body->>'purpose_id')::uuid; u:=(body->>'user_id')::uuid;
  PERFORM cv.auth_staff_record(u);
  SELECT * INTO v FROM cv.policy_version WHERE (tenant_id,id,kind)=(w.tenant_id,p,'purpose') FOR SHARE;
  IF NOT FOUND OR NOT cv.policy_live_at(w.tenant_id,p,'purpose',clock_timestamp()) THEN
   RAISE EXCEPTION 'ACCESS_DENIED' USING ERRCODE='42501'; END IF;
  SELECT revision INTO old_revision FROM cv.auth_grant_revision
   WHERE (tenant_id,user_id,purpose_id)=(w.tenant_id,u,p) FOR UPDATE;
  old_revision:=coalesce(old_revision,0);
  IF old_revision IS DISTINCT FROM (body->>'expected_revision')::integer THEN
   RAISE EXCEPTION 'REVISION_CONFLICT' USING ERRCODE='40001'; END IF;
  active_value:=(body->>'active')::boolean;
  IF active_value IS NULL THEN RAISE EXCEPTION 'INPUT_INVALID' USING ERRCODE='23514'; END IF;
  INSERT INTO cv.purpose_grant VALUES(w.tenant_id,u,p,active_value)
  ON CONFLICT(tenant_id,user_id,purpose_id) DO UPDATE SET active=excluded.active;
  INSERT INTO cv.auth_grant_revision VALUES(w.tenant_id,u,p,old_revision+1)
  ON CONFLICT(tenant_id,user_id,purpose_id) DO UPDATE SET revision=excluded.revision;
  result:=jsonb_build_object('user_id',u,'purpose_id',p,'active',active_value,'revision',old_revision+1);
 END IF;
 INSERT INTO cv.auth_command VALUES(w.instance_id,(a->>'user_id')::uuid,op,key,payload,result);
 INSERT INTO cv.auth_audit(instance_id,actor_id,action,record_id)
 VALUES(w.instance_id,(a->>'user_id')::uuid,op,p);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION cv.auth_revoke(sid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE a jsonb; target cv.staff_session; BEGIN
 a:=cv.auth_current();
 SELECT * INTO target FROM cv.staff_session WHERE (tenant_id,id)=((a->>'tenant_id')::uuid,sid) FOR UPDATE;
 IF NOT FOUND OR (target.user_id<>(a->>'user_id')::uuid AND a->>'role'<>'admin') THEN
  RAISE EXCEPTION 'ACCESS_DENIED' USING ERRCODE='42501'; END IF;
 IF sid=(a->>'session_id')::uuid THEN
  RAISE EXCEPTION 'USE_LOGOUT' USING ERRCODE='23514'; END IF;
 IF target.revoked_at IS NULL THEN
  UPDATE cv.staff_session SET revoked_at=clock_timestamp() WHERE (tenant_id,id)=(target.tenant_id,sid);
  INSERT INTO cv.auth_audit(instance_id,actor_id,action,record_id)
  VALUES((a->>'instance_id')::uuid,(a->>'user_id')::uuid,'session-revoke',sid);
 END IF;
END $function$

CREATE OR REPLACE FUNCTION cv.auth_staff_write(op text, key uuid, payload cv.digest, body jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE a jsonb; w cv.auth_installation; prior cv.auth_command; result jsonb; u uuid;
 member cv.membership; credential text; BEGIN
 a:=cv.auth_current(); PERFORM cv.require_authority((a->>'tenant_id')::uuid,true);
 SELECT * INTO w FROM cv.auth_installation WHERE singleton FOR UPDATE;
 IF key IS NULL OR payload IS NULL OR op NOT IN ('staff-create','staff-update') THEN
  RAISE EXCEPTION 'INPUT_INVALID' USING ERRCODE='23514'; END IF;
 SELECT * INTO prior FROM cv.auth_command WHERE (instance_id,actor_id,operation,operation_key)=
 (w.instance_id,(a->>'user_id')::uuid,op,key);
 IF FOUND THEN
  IF prior.payload_digest<>payload THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT' USING ERRCODE='23514'; END IF;
  PERFORM cv.auth_staff_record((prior.result->>'user_id')::uuid);
  RETURN prior.result;
 END IF;
 IF body->>'role' NOT IN ('admin','recruiter') OR body->>'role' IS NULL THEN
  RAISE EXCEPTION 'INPUT_INVALID' USING ERRCODE='23514'; END IF;
 IF op='staff-create' THEN
  IF (SELECT count(*) FROM cv.staff_user WHERE tenant_id=w.tenant_id)>=(w.policy->>'staff_limit')::integer
  THEN RAISE EXCEPTION 'STAFF_LIMIT' USING ERRCODE='23514'; END IF;
  credential:=body->>'credential_hash';
  IF credential IS NULL OR credential NOT LIKE '$argon2id$v=19$%' OR body->>'login_name' IS NULL
  OR body->>'login_name' !~ '^[a-z0-9][a-z0-9._-]{0,63}$' THEN
   RAISE EXCEPTION 'INPUT_INVALID' USING ERRCODE='23514'; END IF;
  u:=gen_random_uuid();
  INSERT INTO cv.staff_user(tenant_id,id,login_name,credential_hash,active)
  VALUES(w.tenant_id,u,body->>'login_name',credential,true);
  INSERT INTO cv.membership VALUES(w.tenant_id,u,body->>'role',true,1);
 ELSE
  u:=(body->>'user_id')::uuid;
  SELECT * INTO member FROM cv.membership WHERE (tenant_id,user_id)=(w.tenant_id,u) FOR UPDATE;
  IF NOT FOUND OR u=(a->>'user_id')::uuid THEN
   RAISE EXCEPTION 'ACCESS_DENIED' USING ERRCODE='42501'; END IF;
  IF member.revision IS DISTINCT FROM (body->>'expected_revision')::integer THEN
   RAISE EXCEPTION 'REVISION_CONFLICT' USING ERRCODE='40001'; END IF;
  IF body->>'active' IS NULL THEN RAISE EXCEPTION 'INPUT_INVALID' USING ERRCODE='23514'; END IF;
  UPDATE cv.membership SET role=body->>'role',active=(body->>'active')::boolean,revision=revision+1
  WHERE (tenant_id,user_id)=(w.tenant_id,u);
  UPDATE cv.staff_user SET active=(body->>'active')::boolean WHERE (tenant_id,id)=(w.tenant_id,u);
  UPDATE cv.staff_session SET revoked_at=clock_timestamp()
  WHERE (tenant_id,user_id)=(w.tenant_id,u) AND revoked_at IS NULL;
 END IF;
 result:=cv.auth_staff_record(u);
 INSERT INTO cv.auth_command VALUES(w.instance_id,(a->>'user_id')::uuid,op,key,payload,result);
 INSERT INTO cv.auth_audit(instance_id,actor_id,action,record_id)
 VALUES(w.instance_id,(a->>'user_id')::uuid,op,u);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION cv.auth_validate_transaction()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE p record; a jsonb; instant timestamptz; BEGIN
 PERFORM cv.auth_policy_obligations();
 FOR p IN SELECT * FROM pg_temp.cv_auth_policy_obligations ORDER BY tenant_id,policy_id LOOP
  IF p.transaction_id<>pg_current_xact_id() THEN
   RAISE EXCEPTION 'AUTH_CONTEXT_INVALID' USING ERRCODE='42501'; END IF;
  PERFORM 1 FROM cv.policy_version WHERE (tenant_id,id)=(p.tenant_id,p.policy_id) FOR SHARE;
 END LOOP;
 -- The base finalizer now takes any remaining business locks and validates those obligations.
 PERFORM cv.validate_transaction();
 a:=cv.auth_current(); instant:=clock_timestamp();
 IF (a->>'expires_at')::timestamptz<=instant THEN
  RAISE EXCEPTION 'AUTH_REVOKED' USING ERRCODE='42501'; END IF;
 FOR p IN SELECT * FROM pg_temp.cv_auth_policy_obligations LOOP
  IF a->>'role'<>'admin' OR (a->>'tenant_id')::uuid<>p.tenant_id
  OR NOT EXISTS(SELECT 1 FROM cv.policy_version v WHERE (v.tenant_id,v.id)=(p.tenant_id,p.policy_id)
   AND v.activated_at<=instant AND v.expires_at>instant
   AND NOT EXISTS(SELECT 1 FROM cv.policy_revocation r WHERE (r.tenant_id,r.policy_id)=(v.tenant_id,v.id)))
  THEN RAISE EXCEPTION 'POLICY_AUTH_REVOKED' USING ERRCODE='42501'; END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION cv.calculation_binding_check()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE expected jsonb;
BEGIN
 IF NEW.source_profile_id IS NULL THEN
  RAISE EXCEPTION 'PROFILE_SOURCE_REQUIRED' USING ERRCODE='23514'; END IF;
 expected:=cv.calculation_snapshot_v2(NEW.tenant_id,NEW.scope_id,NEW.rubric_id,NEW.source_profile_id);
 IF expected IS NULL OR NEW.calculation_definition IS DISTINCT FROM expected
 OR NEW.calculation_digest<>cv.canonical_digest_v1(expected) THEN
  RAISE EXCEPTION 'CALCULATION_BINDING_MISMATCH' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM cv.profile_revision p WHERE
 (p.tenant_id,p.scope_id,p.id)=(NEW.tenant_id,NEW.scope_id,NEW.source_profile_id)
 AND cv.canonical_digest_v1(p.factual_content)=NEW.factual_digest) THEN
  RAISE EXCEPTION 'FACT_CONTENT_REQUIRED' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION cv.canonical_json_v1(value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE result jsonb;
BEGIN
 CASE jsonb_typeof(value)
 WHEN 'object' THEN
  SELECT coalesce(jsonb_object_agg(key,cv.canonical_json_v1(v) ORDER BY key),'{}'::jsonb)
  INTO result FROM jsonb_each(value) AS entry(key,v);
 WHEN 'array' THEN
  SELECT coalesce(jsonb_agg(cv.canonical_json_v1(v) ORDER BY ordinal),'[]'::jsonb)
  INTO result FROM jsonb_array_elements(value) WITH ORDINALITY AS entry(v,ordinal);
 WHEN 'number' THEN result:=to_jsonb(trim_scale((value#>>'{}')::numeric));
 ELSE result:=value;
 END CASE;
 RETURN result;
END $function$

