CREATE OR REPLACE FUNCTION cv.command_begin(t uuid, p uuid, op text, k uuid, payload cv.digest)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE a uuid; found_result cv.command_result; BEGIN
 a:=cv.require_authority(t,false);
 PERFORM cv.register_obligation('purpose',t,a,p);
 PERFORM pg_advisory_xact_lock(hashtextextended(t::text||a::text||p::text||op||k::text,0));
 SELECT * INTO found_result FROM cv.command_result WHERE
 (tenant_id,actor_id,purpose_id,operation,operation_key)=(t,a,p,op,k);
 IF FOUND THEN
  IF found_result.payload_digest<>payload THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT' USING ERRCODE='23514'; END IF;
  IF found_result.scope_id IS NOT NULL THEN PERFORM cv.lock_scope(t,found_result.scope_id); END IF;
  RETURN found_result.result_id;
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION cv.ensure_obligations()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
BEGIN
 IF to_regclass('pg_temp.cv_authority_obligations') IS NULL THEN
  CREATE TEMPORARY TABLE cv_authority_obligations (
   backend_pid integer NOT NULL DEFAULT pg_backend_pid(),
   transaction_id xid8 NOT NULL DEFAULT pg_current_xact_id(),
   kind text NOT NULL CHECK(kind IN ('scope','purpose','public','erasure')),
   tenant_id uuid NOT NULL, actor_id uuid, subject_id uuid NOT NULL,
   UNIQUE NULLS NOT DISTINCT(kind,tenant_id,actor_id,subject_id)
  ) ON COMMIT DROP;
  ALTER TABLE pg_temp.cv_authority_obligations ENABLE ROW LEVEL SECURITY;
  ALTER TABLE pg_temp.cv_authority_obligations FORCE ROW LEVEL SECURITY;
  CREATE POLICY guard ON pg_temp.cv_authority_obligations TO cv_guard USING(true) WITH CHECK(true);
  REVOKE ALL ON pg_temp.cv_authority_obligations FROM PUBLIC;
 ELSIF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=to_regclass('pg_temp.cv_authority_obligations')
   AND relowner='cv_guard'::regrole AND relkind='r' AND relpersistence='t'
   AND relrowsecurity AND relforcerowsecurity) THEN
  RAISE EXCEPTION 'TRANSACTION_STATE_INVALID' USING ERRCODE='42501';
 END IF;
END $function$

CREATE OR REPLACE FUNCTION cv.erase_scope(scope uuid, request_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE a record; p uuid; BEGIN
 SELECT * INTO a FROM cv.current_authority();
 IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE='42501'; END IF;
 PERFORM cv.require_authority(a.tenant_id,true);
 SELECT purpose_id INTO p FROM cv.privacy_scope WHERE (tenant_id,id)=(a.tenant_id,scope) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 -- Erasure must still work after consent expiry/revocation; admin and erasure policy are separate authority.
 IF NOT EXISTS(SELECT 1 FROM cv.privacy_scope s WHERE (s.tenant_id,s.id)=(a.tenant_id,scope)
 AND cv.policy_live(s.tenant_id,s.erasure_policy_id,'erasure')) THEN
  RAISE EXCEPTION 'ERASURE_POLICY_REQUIRED' USING ERRCODE='42501'; END IF;
 INSERT INTO cv.erasure_request(tenant_id,id,scope_id,actor_id,status) VALUES(a.tenant_id,request_id,scope,a.user_id,'requested');
 INSERT INTO cv.erasure_file SELECT a.tenant_id,request_id,object_key,NULL FROM cv.file_intent WHERE (tenant_id,scope_id)=(a.tenant_id,scope);
 INSERT INTO cv.erasure_context VALUES(pg_backend_pid(),pg_current_xact_id(),a.tenant_id,scope)
 ON CONFLICT(backend_pid) DO UPDATE SET transaction_id=excluded.transaction_id,tenant_id=excluded.tenant_id,scope_id=excluded.scope_id;
 DELETE FROM cv.privacy_scope WHERE (tenant_id,id)=(a.tenant_id,scope);
 UPDATE cv.erasure_request SET status=CASE WHEN EXISTS(SELECT 1 FROM cv.erasure_file WHERE (tenant_id,cv.erasure_file.request_id)=(a.tenant_id,erase_scope.request_id))
 THEN 'files_pending' ELSE 'database_purged' END WHERE (tenant_id,id)=(a.tenant_id,erase_scope.request_id);
 DELETE FROM cv.erasure_context WHERE backend_pid=pg_backend_pid();
 RETURN request_id;
END $function$

CREATE OR REPLACE FUNCTION cv.erasure_policy_pin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
BEGIN
 IF TG_OP='INSERT' THEN
  SELECT erasure_policy_id INTO NEW.erasure_policy_id FROM cv.privacy_scope
  WHERE (tenant_id,id)=(NEW.tenant_id,NEW.scope_id) FOR UPDATE;
  IF NEW.erasure_policy_id IS NULL THEN
   RAISE EXCEPTION 'ERASURE_POLICY_REQUIRED' USING ERRCODE='42501'; END IF;
  PERFORM 1 FROM cv.policy_version WHERE (tenant_id,id)=(NEW.tenant_id,NEW.erasure_policy_id) FOR SHARE;
  IF session_user='cv_runtime' THEN
   PERFORM cv.register_obligation('erasure',NEW.tenant_id,NEW.actor_id,NEW.erasure_policy_id);
  END IF;
 ELSIF NEW.erasure_policy_id IS DISTINCT FROM OLD.erasure_policy_id THEN
  RAISE EXCEPTION 'ERASURE_POLICY_IMMUTABLE' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION cv.final_authority_check()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE t uuid; s uuid; BEGIN
 IF session_user<>'cv_runtime' THEN RETURN NULL; END IF;
 t := (to_jsonb(NEW)->>'tenant_id')::uuid;
 IF TG_TABLE_NAME IN ('policy_version','policy_revocation') THEN
  PERFORM cv.require_authority(t,true);
 ELSE
  s := (to_jsonb(NEW)->>'scope_id')::uuid;
  IF NOT cv.tenant_allowed(t) OR (s IS NOT NULL AND NOT cv.scope_allowed(t,s)) THEN
   RAISE EXCEPTION 'AUTH_REVOKED' USING ERRCODE='42501'; END IF;
 END IF;
