END $function$

CREATE OR REPLACE FUNCTION cv.final_public_acceptance_check()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE p cv.publication; s cv.privacy_scope; g cv.public_upload_grant; at_commit timestamptz;
BEGIN
 -- All callers, including trusted ingestion, must satisfy the same final check.
 SELECT * INTO p FROM cv.publication WHERE (tenant_id,id)=(NEW.tenant_id,NEW.publication_id) FOR UPDATE;
 SELECT * INTO s FROM cv.privacy_scope WHERE (tenant_id,id)=(NEW.tenant_id,NEW.scope_id) FOR SHARE;
 SELECT * INTO g FROM cv.public_upload_grant WHERE (tenant_id,id)=(NEW.tenant_id,NEW.upload_grant_id) FOR SHARE;
 at_commit:=clock_timestamp();
 IF p.id IS NULL OR s.id IS NULL OR g.id IS NULL OR NOT cv.publication_open(p.tenant_id,p.id)
 OR p.snapshot_id<>NEW.snapshot_id OR p.expires_at<=at_commit OR g.expires_at<=at_commit
 OR s.revoked_at IS NOT NULL OR s.consent_expires_at<=at_commit
 OR EXISTS(SELECT 1 FROM cv.policy_version v WHERE v.tenant_id=p.tenant_id
 AND v.id IN (p.purpose_id,p.source_policy_id,p.consent_policy_id,p.retention_policy_id,
 p.erasure_policy_id,p.resource_policy_id) AND v.expires_at<=at_commit) THEN
  RAISE EXCEPTION 'INTAKE_UNAVAILABLE' USING ERRCODE='42501';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION cv.lock_scope(t uuid, s uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE a uuid; p cv.privacy_scope; BEGIN
 a:=cv.require_authority(t,false);
 SELECT * INTO p FROM cv.privacy_scope WHERE (tenant_id,id)=(t,s) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM cv.purpose_grant WHERE (tenant_id,user_id,purpose_id)=(t,a,p.purpose_id) FOR SHARE;
 PERFORM 1 FROM cv.policy_version WHERE tenant_id=t AND id IN
 (p.purpose_id,p.source_policy_id,p.consent_policy_id,p.retention_policy_id,p.erasure_policy_id,p.resource_policy_id)
 ORDER BY id FOR SHARE;
 IF NOT cv.scope_allowed(t,s) THEN RAISE EXCEPTION 'SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 PERFORM cv.register_obligation('scope',t,a,s);
 RETURN p.purpose_id;
END $function$

CREATE OR REPLACE FUNCTION cv.move_stage(scope uuid, application uuid, expected_revision integer, target cv.stage, reason text, operation_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE a record; row cv.application; p uuid; h cv.digest; result uuid; allowed boolean; BEGIN
 SELECT * INTO a FROM cv.current_authority();
 IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE='42501'; END IF;
 p:=cv.lock_scope(a.tenant_id,scope);
 h:=encode(sha256(convert_to(jsonb_build_array(scope,application,expected_revision,target,reason)::text,'UTF8')),'hex');
 result:=cv.command_begin(a.tenant_id,p,'application.stage',operation_key,h);
 IF result IS NOT NULL THEN RETURN result; END IF;
 SELECT * INTO row FROM cv.application WHERE (tenant_id,scope_id,id)=(a.tenant_id,scope,move_stage.application) FOR UPDATE;
 IF NOT FOUND OR row.revision IS DISTINCT FROM expected_revision OR row.removed_at IS NOT NULL THEN
  RAISE EXCEPTION 'REVISION_CONFLICT' USING ERRCODE='40001'; END IF;
 allowed:= (row.stage='received' AND target='evaluating')
 OR (row.stage='evaluating' AND target='interview') OR (row.stage='interview' AND target='hired')
 OR (row.stage IN ('received','evaluating','interview') AND target='not_continuing')
 OR (coalesce(btrim(reason),'')<>'' AND ((row.stage='evaluating' AND target='received')
 OR (row.stage='interview' AND target='evaluating')
 OR (row.stage IN ('hired','not_continuing') AND target='received' AND a.role='admin')));
 IF allowed IS NOT TRUE THEN RAISE EXCEPTION 'STAGE_TRANSITION_DENIED' USING ERRCODE='23514'; END IF;
 UPDATE cv.application SET stage=target,revision=revision+1 WHERE (tenant_id,scope_id,id)=(a.tenant_id,scope,move_stage.application);
 result:=gen_random_uuid();
 INSERT INTO cv.stage_event(tenant_id,scope_id,id,application_id,from_stage,to_stage,revision,actor_id,reason)
 VALUES(a.tenant_id,scope,result,application,row.stage,target,row.revision+1,a.user_id,reason);
 PERFORM cv.command_finish(a.tenant_id,p,'application.stage',operation_key,h,scope,result);
 RETURN result;
END $function$

