CREATE OR REPLACE FUNCTION cv.review_intake(scope uuid, intake_id uuid, expected_revision integer, decision text, chosen_candidate uuid, reason text, operation_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE a record; i cv.intake; p uuid; h cv.digest; result uuid; person uuid; app uuid; position uuid; BEGIN
 SELECT * INTO a FROM cv.current_authority();
 IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE='42501'; END IF;
 p:=cv.lock_scope(a.tenant_id,scope);
 h:=encode(sha256(convert_to(jsonb_build_array(scope,intake_id,expected_revision,decision,chosen_candidate,reason)::text,'UTF8')),'hex');
 result:=cv.command_begin(a.tenant_id,p,'intake.review',operation_key,h);
 IF result IS NOT NULL THEN RETURN result; END IF;
 SELECT * INTO i FROM cv.intake WHERE (tenant_id,scope_id,id)=(a.tenant_id,scope,review_intake.intake_id) FOR UPDATE;
 IF NOT FOUND OR i.revision IS DISTINCT FROM expected_revision OR i.state<>'pending' OR coalesce(btrim(reason),'')=''
 OR decision IS NULL OR decision NOT IN ('link','create','reject') THEN RAISE EXCEPTION 'REVIEW_CONFLICT' USING ERRCODE='23514'; END IF;
 IF decision IN ('link','create') THEN
  IF NOT EXISTS(SELECT 1 FROM cv.document_version d JOIN cv.file_intent f
  ON (f.tenant_id,f.scope_id,f.id)=(d.tenant_id,d.scope_id,d.intent_id)
  WHERE (d.tenant_id,d.scope_id,d.id)=(a.tenant_id,scope,i.document_id) AND f.state='finalized') THEN
   RAISE EXCEPTION 'FILE_NOT_FINALIZED' USING ERRCODE='23514'; END IF;
  IF decision='create' THEN
   IF chosen_candidate IS NOT NULL THEN RAISE EXCEPTION 'REVIEW_INVALID' USING ERRCODE='23514'; END IF;
   person:=gen_random_uuid(); INSERT INTO cv.candidate VALUES(a.tenant_id,person,1,NULL);
  ELSE
   person:=chosen_candidate;
   IF NOT EXISTS(SELECT 1 FROM cv.candidate c WHERE (c.tenant_id,c.id)=(a.tenant_id,person) AND c.removed_at IS NULL
   AND EXISTS(SELECT 1 FROM cv.privacy_scope s WHERE (s.tenant_id,s.candidate_id)=(c.tenant_id,c.id) AND cv.scope_allowed(s.tenant_id,s.id)))
   THEN RAISE EXCEPTION 'PERSON_DENIED' USING ERRCODE='42501'; END IF;
  END IF;
  UPDATE cv.privacy_scope SET candidate_id=person WHERE (tenant_id,id)=(a.tenant_id,scope);
  SELECT position_id INTO position FROM cv.publication_snapshot WHERE (tenant_id,id)=(a.tenant_id,i.snapshot_id);
  app:=gen_random_uuid(); INSERT INTO cv.application VALUES(a.tenant_id,scope,app,person,position,'received',1,NULL);
 ELSE
  IF chosen_candidate IS NOT NULL THEN RAISE EXCEPTION 'REVIEW_INVALID' USING ERRCODE='23514'; END IF;
 END IF;
 result:=gen_random_uuid();
 INSERT INTO cv.intake_review VALUES(a.tenant_id,scope,result,i.id,decision,person,app,a.user_id,reason,clock_timestamp());
 UPDATE cv.intake SET state=CASE WHEN decision='reject' THEN 'rejected' ELSE 'linked' END,revision=revision+1
 WHERE (tenant_id,scope_id,id)=(a.tenant_id,scope,i.id);
 PERFORM cv.command_finish(a.tenant_id,p,'intake.review',operation_key,h,scope,result);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION cv.rubric_total_check()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE t uuid; r uuid; BEGIN
 t:=NEW.tenant_id;
 IF TG_TABLE_NAME='rubric_version' THEN r:=NEW.id; ELSE r:=NEW.rubric_id; END IF;
 IF (SELECT coalesce(sum(weight),0) FROM cv.rubric_criterion WHERE tenant_id=t AND rubric_id=r)<>100
 THEN RAISE EXCEPTION 'RUBRIC_WEIGHT_SUM' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION cv.scope_policy_check()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE p uuid; k text; v cv.policy_version; BEGIN
 -- Revocation removes authority even after its original policies expire.
 IF TG_OP='UPDATE' AND OLD.revoked_at IS NULL AND NEW.revoked_at IS NOT NULL
 AND (to_jsonb(OLD)-'revoked_at')=(to_jsonb(NEW)-'revoked_at') THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND NEW.candidate_id IS DISTINCT FROM OLD.candidate_id
 AND (OLD.revoked_at IS NOT NULL OR OLD.consent_expires_at<=clock_timestamp()) THEN
  RAISE EXCEPTION 'INACTIVE_SCOPE_LINK_DENIED' USING ERRCODE='23514'; END IF;
 FOR p,k IN SELECT * FROM (VALUES(NEW.purpose_id,'purpose'),(NEW.source_policy_id,'source'),
 (NEW.consent_policy_id,'consent'),(NEW.retention_policy_id,'retention'),
 (NEW.erasure_policy_id,'erasure'),(NEW.resource_policy_id,'resource')) AS required(id,kind) LOOP
  SELECT * INTO v FROM cv.policy_version WHERE tenant_id=NEW.tenant_id AND id=p FOR SHARE;
  IF NOT FOUND OR v.kind<>k OR NOT cv.policy_live(NEW.tenant_id,p,k)
  OR (v.synthetic_only AND NOT NEW.synthetic) OR NEW.consent_expires_at>v.expires_at THEN
   RAISE EXCEPTION 'POLICY_SCOPE_INVALID' USING ERRCODE='23514'; END IF;
 END LOOP;
 IF TG_OP='UPDATE' AND (to_jsonb(OLD)-ARRAY['revoked_at','candidate_id']) IS DISTINCT FROM
 (to_jsonb(NEW)-ARRAY['revoked_at','candidate_id']) THEN
  RAISE EXCEPTION 'PRIVACY_SCOPE_IMMUTABLE' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND OLD.candidate_id IS NOT NULL AND NEW.candidate_id IS DISTINCT FROM OLD.candidate_id THEN
  RAISE EXCEPTION 'PERSON_LINK_IMMUTABLE' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at THEN
  RAISE EXCEPTION 'REVOCATION_IMMUTABLE' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION cv.tenant_allowed(t uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE a record;
BEGIN
 SELECT authority.user_id,g.purpose_id INTO a FROM cv.current_authority() authority
 JOIN cv.purpose_grant g ON (g.tenant_id,g.user_id)=(authority.tenant_id,authority.user_id)
 WHERE authority.tenant_id=t AND g.active AND cv.policy_live(t,g.purpose_id,'purpose')
 ORDER BY g.purpose_id LIMIT 1;
 IF NOT FOUND THEN RETURN false; END IF;
 PERFORM cv.register_obligation('purpose',t,a.user_id,a.purpose_id);
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION cv.upload_grant_binding_check()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF (to_jsonb(NEW)-'scope_id') IS DISTINCT FROM (to_jsonb(OLD)-'scope_id')
  OR OLD.scope_id IS NOT NULL AND NEW.scope_id IS DISTINCT FROM OLD.scope_id THEN
   RAISE EXCEPTION 'UPLOAD_GRANT_IMMUTABLE' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM cv.publication p JOIN cv.publication_snapshot s
 ON (s.tenant_id,s.position_id)=(p.tenant_id,p.position_id)
 WHERE (p.tenant_id,p.id,s.id)=(NEW.tenant_id,NEW.publication_id,NEW.snapshot_id)) THEN
  RAISE EXCEPTION 'PUBLICATION_SNAPSHOT_MISMATCH' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION cv.validate_transaction()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'cv'
AS $function$
DECLARE o record; context cv.transaction_context; s cv.privacy_scope; p cv.publication;
 i cv.intake; g cv.public_upload_grant; instant timestamptz; staff_role text; cap integer;
BEGIN
 IF session_user NOT IN ('cv_runtime','cv_public') THEN
  RAISE EXCEPTION 'TRANSACTION_ROLE_INVALID' USING ERRCODE='42501'; END IF;
 PERFORM cv.ensure_obligations();
 IF session_user='cv_runtime' THEN
  SELECT * INTO context FROM cv.transaction_context WHERE backend_pid=pg_backend_pid()
  AND transaction_id=pg_current_xact_id();
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE='42501'; END IF;
  PERFORM 1 FROM cv.staff_session ss JOIN cv.membership m
  ON (m.tenant_id,m.user_id)=(ss.tenant_id,ss.user_id)
  JOIN cv.staff_user u ON (u.tenant_id,u.id)=(m.tenant_id,m.user_id)
  WHERE (ss.tenant_id,ss.id,ss.user_id)=(context.tenant_id,context.session_id,context.user_id)
  FOR SHARE OF ss,m,u;
 END IF;
 -- Acquire every potentially blocking lock before taking the validation clock.
 FOR o IN SELECT * FROM pg_temp.cv_authority_obligations ORDER BY kind,tenant_id,subject_id LOOP
  IF o.backend_pid<>pg_backend_pid() OR o.transaction_id<>pg_current_xact_id() THEN
   RAISE EXCEPTION 'TRANSACTION_STATE_INVALID' USING ERRCODE='42501'; END IF;
  IF o.kind='scope' THEN
   SELECT * INTO s FROM cv.privacy_scope WHERE (tenant_id,id)=(o.tenant_id,o.subject_id) FOR SHARE;
   PERFORM 1 FROM cv.purpose_grant WHERE (tenant_id,user_id,purpose_id)=
    (o.tenant_id,o.actor_id,s.purpose_id) FOR SHARE;
   PERFORM cv.lock_authority_policies(o.tenant_id,to_jsonb(s));
  ELSIF o.kind='purpose' THEN
   PERFORM 1 FROM cv.purpose_grant WHERE (tenant_id,user_id,purpose_id)=
    (o.tenant_id,o.actor_id,o.subject_id) FOR SHARE;
   PERFORM 1 FROM cv.policy_version WHERE (tenant_id,id)=(o.tenant_id,o.subject_id) FOR SHARE;
  ELSIF o.kind='erasure' THEN
   PERFORM 1 FROM cv.policy_version WHERE (tenant_id,id)=(o.tenant_id,o.subject_id) FOR SHARE;
  ELSE
   SELECT * INTO i FROM cv.intake WHERE (tenant_id,receipt)=(o.tenant_id,o.subject_id) FOR SHARE;
   SELECT * INTO p FROM cv.publication WHERE (tenant_id,id)=(i.tenant_id,i.publication_id) FOR SHARE;
   PERFORM 1 FROM cv.position j JOIN cv.company c ON (c.tenant_id,c.id)=(j.tenant_id,j.company_id)
    WHERE (j.tenant_id,j.id)=(p.tenant_id,p.position_id) FOR SHARE OF j,c;
   PERFORM 1 FROM cv.privacy_scope WHERE (tenant_id,id)=(i.tenant_id,i.scope_id) FOR SHARE;
   PERFORM 1 FROM cv.public_upload_grant WHERE (tenant_id,id)=(i.tenant_id,i.upload_grant_id) FOR SHARE;
   PERFORM cv.lock_authority_policies(o.tenant_id,to_jsonb(p));
  END IF;
 END LOOP;
 instant:=clock_timestamp();
 IF session_user='cv_runtime' THEN
  SELECT m.role INTO staff_role FROM cv.staff_session ss JOIN cv.membership m
  ON (m.tenant_id,m.user_id)=(ss.tenant_id,ss.user_id)
  JOIN cv.staff_user u ON (u.tenant_id,u.id)=(m.tenant_id,m.user_id)
  WHERE (ss.tenant_id,ss.id,ss.user_id)=(context.tenant_id,context.session_id,context.user_id)
  AND ss.revoked_at IS NULL AND ss.expires_at>instant AND m.active AND u.active;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_REVOKED' USING ERRCODE='42501'; END IF;
 END IF;
 FOR o IN SELECT * FROM pg_temp.cv_authority_obligations ORDER BY kind,tenant_id,subject_id LOOP
  IF o.kind<>'public' AND (session_user<>'cv_runtime' OR
    (o.tenant_id,o.actor_id) IS DISTINCT FROM (context.tenant_id,context.user_id)) THEN
   RAISE EXCEPTION 'AUTH_REVOKED' USING ERRCODE='42501'; END IF;
  IF o.kind='scope' THEN
   SELECT * INTO s FROM cv.privacy_scope WHERE (tenant_id,id)=(o.tenant_id,o.subject_id);
   IF NOT FOUND OR s.revoked_at IS NOT NULL OR s.consent_expires_at<=instant
   OR NOT cv.authority_policies_live(o.tenant_id,to_jsonb(s),instant)
   OR NOT EXISTS(SELECT 1 FROM cv.purpose_grant WHERE (tenant_id,user_id,purpose_id)=
    (o.tenant_id,o.actor_id,s.purpose_id) AND active) THEN
    RAISE EXCEPTION 'SCOPE_DENIED' USING ERRCODE='42501'; END IF;
  ELSIF o.kind='purpose' THEN
   IF NOT cv.policy_live_at(o.tenant_id,o.subject_id,'purpose',instant)
   OR NOT EXISTS(SELECT 1 FROM cv.purpose_grant WHERE (tenant_id,user_id,purpose_id)=
    (o.tenant_id,o.actor_id,o.subject_id) AND active) THEN
    RAISE EXCEPTION 'COMMAND_PURPOSE_REVOKED' USING ERRCODE='42501'; END IF;
  ELSIF o.kind='erasure' THEN
   IF staff_role<>'admin' OR NOT cv.policy_live_at(o.tenant_id,o.subject_id,'erasure',instant) THEN
    RAISE EXCEPTION 'ERASURE_AUTH_REVOKED' USING ERRCODE='42501'; END IF;
  ELSE
   IF session_user<>'cv_public' THEN RAISE EXCEPTION 'TRANSACTION_ROLE_INVALID' USING ERRCODE='42501'; END IF;
   SELECT * INTO i FROM cv.intake WHERE (tenant_id,receipt)=(o.tenant_id,o.subject_id);
   SELECT * INTO p FROM cv.publication WHERE (tenant_id,id)=(i.tenant_id,i.publication_id);
   SELECT * INTO s FROM cv.privacy_scope WHERE (tenant_id,id)=(i.tenant_id,i.scope_id);
   SELECT * INTO g FROM cv.public_upload_grant WHERE (tenant_id,id)=(i.tenant_id,i.upload_grant_id);
   SELECT (definition->>'public_submission_quota')::integer INTO cap
    FROM cv.policy_version WHERE (tenant_id,id)=(p.tenant_id,p.resource_policy_id);
   IF p.id IS NULL OR s.id IS NULL OR g.id IS NULL OR p.state<>'published'
   OR p.snapshot_id IS DISTINCT FROM i.snapshot_id OR p.expires_at<=instant OR g.expires_at<=instant
   OR s.revoked_at IS NOT NULL OR s.consent_expires_at<=instant
   OR NOT cv.authority_policies_live(o.tenant_id,to_jsonb(p),instant)
   OR cap IS NULL OR cap<=0 OR (SELECT count(*) FROM cv.intake
    WHERE (tenant_id,publication_id)=(p.tenant_id,p.id))>cap
   OR NOT EXISTS(SELECT 1 FROM cv.position j JOIN cv.company c
    ON (c.tenant_id,c.id)=(j.tenant_id,j.company_id)
    WHERE (j.tenant_id,j.id)=(p.tenant_id,p.position_id) AND j.removed_at IS NULL AND c.removed_at IS NULL) THEN
    RAISE EXCEPTION 'INTAKE_UNAVAILABLE' USING ERRCODE='42501'; END IF;
  END IF;
 END LOOP;
END $function$
